    "question": "Cas clinique — À la suite d'une intervention chirurgicale nécessaire et urgente en vue de traiter une carotidie sévère, le chirurgien avait omis d'informer le patient du risque qui s'était malencontreusement réalisé, (monsieur X a été atteint d'un risque rare inhérent à ce type d'opération, à savoir une hémiplégie). Il décéda trois ans plus tard, après que son état de santé ne se soit continuellement dégradé. Sa veuve et son fils intentent une action contre le chirurgien. — Question : Le chirurgien pourra être poursuivi devant :",
