    "question": "Cas clinique — Monsieur et Madame D. se sont blessés lors d'une randonnée fin octobre 2008. En raison des conditions météorologiques, leur transfert n'a pu avoir lieu que plusieurs heures après l'accident. Monsieur présente une plaie ouverte sans caractère de gravité, le médecin urgentiste recoud la plaie et le garde en observation 24 h. L'état de Madame D. est plus sérieux, aggravé en raison du temps qui s'est écoulé entre l'accident et son arrivée à l'hôpital, et nécessite une opération. Le chef de service étant occupé, il confie le soin de pratiquer l'opération à un autre médecin du service. L'intervention de Madame D. se passe bien mais elle conserve une gêne, ce qui selon les médecins, fait partie des risques inhérents à ce type d'intervention. Deux jours après sa sortie de l'hôpital, Madame déclare une infection liée à un microbe qui entraîne un arrêt de travail de plusieurs semaines. Les époux D souhaitent se voir réparer les divers préjudices qu'ils ont subis. La question se pose alors de savoir quelles sont les possibilités de recours dont disposent M. et Mme D, les moyens juridiques qu'ils peuvent invoquer et leurs chances de succès en cas de recours. — Question : Dans cette situation, qui peut voir sa responsabilité engagée ?",
    "propositions": {
      "A": "L'hôpital",
      "B": "Le médecin chef de service",
      "C": "Le médecin qui réalisé l'acte chirurgical",
      "D": "Personne",
      "E": "L'hôpital et le médecin chef de service"
    },
