    "question": "Cas clinique — Durant votre garde, les services de police conduisent aux urgences de l’hôpital un homme interpellé en état d’ivresse sur la voie publique. À son arrivée, vous constatez que l’homme ivre présente des contusions sur le visage et qu’il est visiblement confus et désorienté. Les policiers vous expliquent alors que l’interpellation de cet homme a été assez musclée, car il refusait d’obtempérer. 02 h plus tard le patient fait un arrêt cardiorespiratoire. Vous faites une réanimation cardiopulmonaire associant massage cardiaque externe, oxygénation pulmonaire à haut débit par sonde d’intubation et six injections itératives d’adrénaline. La réanimation est inefficace et le décès est déclaré. — Question : Quel est la forme médico-légale de la mort que vous devez mentionner sur le certificat de décès ?",
